   Print (W03): black on white, QR and link shown, one photo per event, lot cards kept whole. */
:root{--fg:#1d2b1f;--mut:#56615b;--line:#d6ddd6;--ok:#1b5e20;--okb:#e5f3e6;--warn:#8a4500;--warnb:#fff0d9;--lab:#0d47a1;--labb:#e3edfb}
*{box-sizing:border-box}
body{margin:0;font:16px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,"Noto Sans Tamil","Noto Sans",sans-serif;color:var(--fg);background:#f5f7f4}
header,main,footer{max-width:46rem;margin:0 auto;padding:1rem}
header{background:#fff;border-bottom:1px solid var(--line)}
h1{font-size:1.4rem;line-height:1.3;margin:.25rem 0 .5rem}
h2{font-size:1.15rem;margin:0 0 .5rem}
h3{font-size:1rem;margin:0 0 .5rem}
section,article{background:#fff;border:1px solid var(--line);border-radius:8px;padding:1rem;margin:0 0 1rem}
article{background:#fbfcfa}
dl{display:grid;grid-template-columns:minmax(7rem,38%) 1fr;gap:.3rem .75rem;margin:0}
dt{color:var(--mut);font-size:.9rem}
dd{margin:0;overflow-wrap:anywhere}
ul{margin:.25rem 0;padding-left:1.25rem}
a{color:#0b57d0}
.meta{color:var(--mut);font-size:.9rem;font-weight:400}
.badges{display:flex;flex-wrap:wrap;gap:.5rem;margin:0}
.badge{display:inline-flex;align-items:center;gap:.4rem;margin:0;padding:.3rem .7rem;border:2px solid;border-radius:999px;font-weight:600;font-size:.9rem}
.ok{color:var(--ok);background:var(--okb)}
.warn{color:var(--warn);background:var(--warnb)}
.lab{color:var(--lab);background:var(--labb)}
.st{font-weight:600}
.st.ok,.st.warn{background:none}
i{font-style:normal}
.tags{display:flex;flex-wrap:wrap;gap:.3rem;list-style:none;margin:0;padding:0}
.tags li{border:1px solid var(--line);border-radius:4px;padding:0 .4rem;font-size:.9rem;background:#fff}
summary{cursor:pointer;font-weight:600;padding:.6rem 0;min-height:44px}
.tl{list-style:none;margin:.25rem 0 0;padding:0}
.ev{border-left:3px solid var(--line);margin-left:.3rem;padding:.2rem 0 .8rem .8rem}
.ev p{margin:.1rem 0}
.ph{display:inline-block;margin:.3rem .3rem 0 0}
.ph img{display:block;width:120px;height:auto;border-radius:4px;background:var(--line)}
.ph.big{display:block}
.ph.big img{width:100%}
footer{color:var(--mut);font-size:.85rem}
footer p{margin:.2rem 0}
.map{margin:.75rem 0 0}
.map svg{display:block;width:100%;max-width:240px;height:auto}
.map path{fill:var(--okb);stroke:var(--ok);stroke-width:.8}
.map circle{fill:var(--warn);stroke:#fff;stroke-width:.6}
.qr{display:none}
@media (min-width:40rem){h1{font-size:1.7rem}.ph img{width:160px}}
@media print{
:root{--fg:#000;--mut:#000;--line:#999;--ok:#000;--okb:#fff;--warn:#000;--warnb:#fff;--lab:#000;--labb:#fff}
body,header{background:#fff;font-size:11pt}
header,main,footer{max-width:none;padding:0}
section,article{border:0;padding:0}
article,.ev{break-inside:avoid}
a{color:#000}
.ph~.ph{display:none}
.qr{display:block;width:120px;height:120px;margin:.5rem 0;background:center/contain no-repeat;-webkit-print-color-adjust:exact;print-color-adjust:exact}
}</style>
</head>
